  const slides=[...document.querySelectorAll('.hero-slide')];
  const dots=[...document.querySelectorAll('.hero-dots button')];
  let current=0, timer, paused=false;
  function show(i){
    current=(i+slides.length)%slides.length;
    slides.forEach((s,n)=>s.classList.toggle('active',n===current));
    dots.forEach((d,n)=>d.classList.toggle('active',n===current));
  }
  function start(){clearInterval(timer);if(!paused)timer=setInterval(()=>show(current+1),5000)}
  dots.forEach((d,i)=>d.addEventListener('click',()=>{show(i);start()}));
  document.getElementById('prev').addEventListener('click',()=>{show(current-1);start()});
  document.getElementById('next').addEventListener('click',()=>{show(current+1);start()});
  document.getElementById('pause').addEventListener('click',function(){
    paused=!paused; this.textContent=paused?'▶':'Ⅱ'; start();
  });
  document.querySelectorAll('.heart').forEach(b=>b.addEventListener('click',function(){
